import {statuses,validateItems,validatePODate,totals,summarizeMonth} from './domain.js';

export const previewStorageKey='po-the-grands-preview-workflow-v2';
export const legacyPreviewStorageKey='po-grands-preview-workflow-v1';
const validStates=new Set(['pending','returned','revision_requested','editing','approved','received','rejected']);
const clone=value=>JSON.parse(JSON.stringify(value));
const eligible=item=>['approved','received'].includes(item.state);
export function detailFinancialSummaries(items){const eligibleItems=items.filter(eligible);return {request:totals(items),eligible:totals(eligibleItems)};}
const snapshot=item=>({department:item.department,name:item.name,spec:item.spec,source:item.source,note:item.note||'',payment_method:item.payment_method,qty:item.qty,unit:item.unit,unit_price:item.unit_price,vat:!!item.vat,base_cents:item.base_cents,tax_cents:item.tax_cents,total_cents:item.total_cents});
const statusOf=po=>{if(po.closed_at)return'closed';const rows=po.items;if(rows.length&&rows.every(i=>i.state==='rejected'))return'rejected';if(rows.some(i=>['pending','returned','revision_requested','editing'].includes(i.state)))return'pending';if(rows.length&&rows.every(i=>i.state==='received'||i.state==='rejected'))return'received';return'approved';};
function refresh(po){const sum=totals(po.items);po.total_cents=sum.total_cents;po.base_cents=sum.base_cents;po.tax_cents=sum.tax_cents;po.confirmed_purchase_cents=po.items.filter(eligible).reduce((n,i)=>n+i.total_cents,0);po.received_cents=po.items.filter(i=>i.state==='received').reduce((n,i)=>n+i.total_cents,0);po.status=statusOf(po);return po;}
function bulkApproveReady(po){const live=po.items.filter(i=>!['received','rejected'].includes(i.state));return live.length>0&&live.some(i=>i.state==='pending')&&live.every(i=>['pending','approved'].includes(i.state));}
function bulkReceiveReady(po){const live=po.items.filter(i=>!['received','rejected'].includes(i.state));return live.length>0&&live.some(i=>i.state==='approved')&&live.every(i=>i.state==='approved');}
function validateFields(fields){const item=validateItems([fields])[0];if(!String(fields.department||'').trim()||!String(fields.unit||'').trim()||!fields.payment_method)throw Error('กรอกแผนก หน่วย และการชำระเงินให้ครบ');if(fields.price_kind!==undefined&&fields.price_kind!=='confirmed')throw Error('โหมดทดลองรองรับเฉพาะราคายืนยันแล้ว');return item;}
export function createPreviewService({storage=globalThis.localStorage,fixtures=[]}={}){
 const read=()=>{try{return JSON.parse(storage.getItem(previewStorageKey)||'null')}catch{return null}};
 const write=value=>storage.setItem(previewStorageKey,JSON.stringify(value));
 const initial=()=>{let data=read();if(data&&data.version===2&&Array.isArray(data.rows)&&data.commands)return data;data={version:2,rows:clone(fixtures),commands:{},notice:'ชุดตัวอย่างรุ่นใหม่เริ่มต้นแล้ว ข้อมูลจากชุดทดลองก่อนหน้านี้ไม่ได้นำเข้ามา'};data.rows.forEach(refresh);write(data);return data;};
 const data=()=>{const state=initial();return clone(state)};
 const canAccess=(po,actor)=>actor?.role==='owner'||actor?.role==='office'&&(actor.can_export_report===true||po.created_by===actor.id);
 const canCreate=actor=>actor?.role==='office';
 const record=(po,action,actor,item=null,reason='',extra={})=>{const event={id:`${po.id}:${po.version}:${action}:${item?.id||'po'}:${po.events.length}`,action,actor_id:actor.id,actor_name:actor.display_name,item_id:item?.id||null,item_name:item?.name||null,item_revision:item?.revision||null,at:new Date().toISOString(),reason,...extra};po.events.push(event);return event;};
 const load=(id,actor)=>{const po=data().rows.find(row=>row.id===id);if(!po||!canAccess(po,actor))throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');return clone(po);};
 const list=(actor,status='',page=1,scope='all')=>{const rows=data().rows.filter(po=>canAccess(po,actor)).filter(po=>!(actor?.role==='office'&&actor.can_export_report&&scope==='mine')||po.created_by===actor.id).filter(po=>!status||po.status===status).sort((a,b)=>b.created_at.localeCompare(a.created_at));return {rows:rows.slice((page-1)*10,page*10),total:rows.length};};
 const stats=(actor,scope='all')=>Object.fromEntries(Object.keys(statuses).map(s=>[s,data().rows.filter(po=>canAccess(po,actor)&&(!(actor?.role==='office'&&actor.can_export_report&&scope==='mine')||po.created_by===actor.id)&&po.status===s).length]));
 function mutate(poId,action,{actor,itemId=null,reason='',confirmed=false,fields=null,key,expectedVersion}={}){
  if(!actor?.id||!['owner','office'].includes(actor.role))throw Error('บัญชีทดลองไม่มีสิทธิ์ทำรายการ');if(!key)throw Error('คำสั่งนี้ไม่มีรหัสป้องกันรายการซ้ำ');const state=data(),po=state.rows.find(row=>row.id===poId);if(!po||!canAccess(po,actor))throw Error('ไม่พบใบ PO หรือไม่มีสิทธิ์เข้าถึง');const ownerActions=['approve_all','reject_all','approve_item','return_item','reject_item','unlock_item','refuse_revision','close'];if(ownerActions.includes(action)&&actor.role!=='owner')throw Error('ทำรายการนี้ได้เฉพาะเจ้าของ');const creatorActions=['request_revision','resubmit'];if(creatorActions.includes(action)&&(actor.role!=='office'||po.created_by!==actor.id))throw Error('ทำรายการได้เฉพาะผู้สร้างใบ PO');if(action==='receive_all'||action==='receive_item'){if(actor.role!=='office'||(!actor.can_export_report&&po.created_by!==actor.id))throw Error('รับสินค้าได้เฉพาะใบ PO ที่มีสิทธิ์เข้าถึง');}
  const fingerprint=JSON.stringify({poId,action,actorId:actor.id,actorRole:actor.role,can_export_report:actor.can_export_report===true,itemId,reason,confirmed,fields});const cached=state.commands[key];if(cached){if(cached.fingerprint!==fingerprint)throw Error('รหัสคำสั่งนี้ถูกใช้กับข้อมูลหรือบัญชีอื่นแล้ว');return clone(cached.result);}if(expectedVersion!==po.version)throw Error('ข้อมูลเปลี่ยนแล้ว กรุณาโหลดรายการล่าสุดก่อนบันทึก');if(po.closed_at)throw Error('ใบ PO ปิดแล้ว แก้ไขไม่ได้');const requiredReason=()=>{const text=String(reason||'').trim();if(!text||text.length>2000)throw Error('ระบุเหตุผลไม่เกิน 2,000 ตัวอักษร');return text;};
  if(action==='approve_all'){if(!bulkApproveReady(po))throw Error('อนุมัติทั้งใบไม่ได้ ยังมีรายการที่ต้องแก้ไขหรือพิจารณาแยก');const pending=po.items.filter(i=>i.state==='pending');for(const item of pending){item.state='approved';item.approved_snapshot=snapshot(item);item.revision++;record(po,'approve',actor,item,reason);} }
  else if(action==='reject_all'){const why=requiredReason();if(!po.items.length||!po.items.every(i=>i.state==='pending'))throw Error('ไม่อนุมัติทั้งใบได้เมื่อทุกรายการยังรออนุมัติ');for(const item of po.items){item.state='rejected';item.reject_reason=why;item.revision++;record(po,'reject',actor,item,why);}}
  else if(action==='approve_item'||action==='return_item'||action==='reject_item'){const item=po.items.find(i=>i.id===itemId);if(!item||item.state!=='pending')throw Error('สถานะรายการเปลี่ยนแล้ว กรุณาโหลดใหม่');const why=['return_item','reject_item'].includes(action)?requiredReason():String(reason||'').trim();item.state=action==='approve_item'?'approved':action==='return_item'?'returned':'rejected';if(action==='approve_item')item.approved_snapshot=snapshot(item);if(action==='return_item')item.return_reason=why;if(action==='reject_item')item.reject_reason=why;item.revision++;record(po,action==='approve_item'?'approve':action==='return_item'?'return':'reject',actor,item,why);}
  else if(action==='request_revision'){const item=po.items.find(i=>i.id===itemId);if(!item||!['pending','approved'].includes(item.state))throw Error('ขอแก้ไขได้เฉพาะรายการที่รอหรือได้รับอนุมัติ');const why=requiredReason();item.paused_from=item.state;item.revision_reason=why;item.state='revision_requested';item.revision++;record(po,'request_revision',actor,item,why);}
  else if(action==='unlock_item'||action==='refuse_revision'){const item=po.items.find(i=>i.id===itemId);if(!item||item.state!=='revision_requested')throw Error('ไม่พบคำขอแก้ไขที่รอพิจารณา');const why=requiredReason();if(action==='unlock_item'){item.state='editing';item.revision++;record(po,'unlock',actor,item,why);}else{item.state=item.paused_from==='approved'?'approved':'pending';item.paused_from=null;item.revision_reason='';item.revision++;record(po,'refuse_revision',actor,item,why);}}
  else if(action==='resubmit'){const item=po.items.find(i=>i.id===itemId);if(!item||!['editing','returned'].includes(item.state)||!fields)throw Error('รายการนี้ยังไม่ได้รับอนุญาตให้แก้ไข');const before=snapshot(item),oldState=item.state,updated=validateFields(fields);Object.assign(item,updated,{state:'pending',revision:item.revision+1});item.paused_from=null;item.revision_reason='';item.return_reason='';record(po,'edit',actor,item,reason,{before,after:snapshot(item),old_amount_cents:before.total_cents,new_amount_cents:item.total_cents,delta_cents:item.total_cents-before.total_cents,from_state:oldState});record(po,'resubmit',actor,item,reason);}
  else if(action==='receive_all'){if(confirmed!==true)throw Error('ยืนยันว่าได้รับสินค้าครบทุกรายการแล้ว');if(!bulkReceiveReady(po))throw Error('รับทั้งใบ PO ได้เมื่อทุกรายการที่เหลือได้รับอนุมัติแล้ว');for(const item of po.items.filter(i=>i.state==='approved')){item.state='received';item.revision++;record(po,'receive',actor,item);}}
  else if(action==='receive_item'){if(confirmed!==true)throw Error('ยืนยันรับสินค้ารายการนี้แล้ว');const item=po.items.find(i=>i.id===itemId);if(!item||item.state!=='approved')throw Error('รับได้เฉพาะรายการที่อนุมัติแล้ว');item.state='received';item.revision++;record(po,'receive',actor,item);}
  else if(action==='close'){if(actor.role!=='owner')throw Error('ทำรายการนี้ได้เฉพาะเจ้าของ');if(confirmed!==true)throw Error('ยืนยันว่าได้รับใบกำกับภาษีแล้ว');if(!po.items.some(i=>i.state==='received')||!po.items.every(i=>['received','rejected'].includes(i.state)))throw Error('ปิดใบ PO ได้เมื่อทุกรายการรับแล้วหรือไม่อนุมัติ และมีอย่างน้อยหนึ่งรายการรับแล้ว');po.closed_at=new Date().toISOString();record(po,'close',actor,null);}
  else throw Error('ไม่รองรับการทำรายการนี้');refresh(po);po.version++;state.commands[key]={fingerprint,result:clone(po)};write(state);return clone(po);
 }
 function create(items,{actor,poDate,key}={}){if(!canCreate(actor))throw Error('สร้างใบ PO ได้เฉพาะพนักงานทดลอง');if(!key)throw Error('คำสั่งนี้ไม่มีรหัสป้องกันรายการซ้ำ');const date=validatePODate(poDate),lines=validateItems(items).map((line,index)=>{const item=validateFields(items[index]);return {...item,id:`${key}-item-${index+1}`,state:'pending',revision:1};});const state=data(),fingerprint=JSON.stringify({action:'create',actorId:actor.id,actorRole:actor.role,poDate:date,items:lines.map(snapshot)});if(state.commands[key]){if(state.commands[key].fingerprint!==fingerprint)throw Error('รหัสคำสั่งนี้ถูกใช้กับข้อมูลหรือบัญชีอื่นแล้ว');return clone(state.commands[key].result);}const now=new Date().toISOString(),po={id:`${key}-po`,po_number:`DEMO-${new Date().getFullYear()}-${String(state.rows.length+1).padStart(5,'0')}`,po_date:date,created_at:now,created_by:actor.id,requester_name:actor.display_name,version:1,closed_at:null,items:lines,events:[]};record(po,'create',actor);refresh(po);state.rows.unshift(po);state.commands[key]={fingerprint,result:clone(po)};write(state);return clone(po);}
 function report(month,actor){if(actor?.role!=='office'||actor.can_export_report!==true)throw Error('รายงานรวมเปิดได้เฉพาะฝ่ายจัดซื้อหลักในโหมดทดลอง');const rows=data().rows.filter(po=>canAccess(po,actor)&&po.po_date.startsWith(month));const eligibleRows=rows.map(po=>({...po,total_cents:po.items.filter(eligible).reduce((n,i)=>n+i.total_cents,0)}));const out=summarizeMonth(eligibleRows);out.rows=rows.map(po=>({...po,total_cents:po.items.filter(eligible).reduce((sum,item)=>sum+item.total_cents,0)}));out.total_cents=rows.reduce((n,po)=>n+po.items.filter(eligible).reduce((sum,i)=>sum+i.total_cents,0),0);out.ordered_count=rows.filter(po=>po.items.some(eligible)).length;out.pending_count=rows.filter(po=>po.items.some(i=>['pending','returned','revision_requested','editing'].includes(i.state))).length;out.rejected_count=rows.filter(po=>po.status==='rejected').length;return out;}
 return {load,list,stats,create,mutate,report,bulkApproveReady,bulkReceiveReady,reset(){write({version:2,rows:clone(fixtures).map(refresh),commands:{},notice:'ชุดตัวอย่างถูกคืนค่าแล้ว'});},notice:()=>data().notice};
}
